internal extension NodeContext {
    init(_ rb: RustBridge.NodeContextRef) throws {
        self.nodeType = try { let rawValue = rb.nodeType().toString(); guard let value = NodeType(rawValue: rawValue) else { throw ConversionError.validation(message: "Unknown NodeType variant", source: rawValue) }; return value }()
        self.tagName = rb.tagName().toString()
