/// The type of an inline text annotation.
///
/// Uses internally tagged representation (`"annotation_type": "bold"`) for JSON serialization.
public enum AnnotationKind: Codable, Sendable, Hashable {
    /// Bold / strong emphasis.
    case bold
    /// Italic / emphasis.
    case italic
    /// Underline.
    case underline
    /// Strikethrough / deleted text.
    case strikethrough
    /// Inline code.
    case code
    /// Subscript text.
    case `subscript`
    /// Superscript text.
    case superscript
    /// Highlighted / marked text.
    case highlight
    /// A hyperlink sourced from an `<a href="...">` element.
    case link(url: String, title: String?)

    private enum CodingKeys: String, CodingKey {
        case annotationType = "annotation_type"

        case title
        case url    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let type = try container.decode(String.self, forKey: .annotationType)
        switch type {
        case "bold":
            self = .bold
        case "italic":
            self = .italic
        case "underline":
            self = .underline
        case "strikethrough":
            self = .strikethrough
        case "code":
            self = .code
        case "subscript":
            self = .`subscript`
        case "superscript":
            self = .superscript
        case "highlight":
            self = .highlight
        case "link":
            self = .link(url: try container.decode(String.self, forKey: .url), title: try container.decodeIfPresent(String.self, forKey: .title))
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .annotationType,
                in: container,
                debugDescription: "Unknown AnnotationKind type: \(type)"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .bold:
            try container.encode("bold", forKey: .annotationType)
        case .italic:
            try container.encode("italic", forKey: .annotationType)
        case .underline:
            try container.encode("underline", forKey: .annotationType)
        case .strikethrough:
            try container.encode("strikethrough", forKey: .annotationType)
        case .code:
            try container.encode("code", forKey: .annotationType)
        case .`subscript`:
            try container.encode("subscript", forKey: .annotationType)
        case .superscript:
            try container.encode("superscript", forKey: .annotationType)
        case .highlight:
            try container.encode("highlight", forKey: .annotationType)
        case .link(let url, let title):
            try container.encode("link", forKey: .annotationType)
            try container.encode(url, forKey: .url)
            try container.encodeIfPresent(title, forKey: .title)

        }
    }
}
extension AnnotationKind {
    /// Returns the serde wire tag identifying this variant -- the same value
    /// the pre-promotion opaque binding's `to_string()` returned -- dropping
    /// any associated payload.
    public func toString() -> String {
        switch self {
        case .bold:
            return "bold"
        case .italic:
            return "italic"
        case .underline:
            return "underline"
        case .strikethrough:
            return "strikethrough"
        case .code:
            return "code"
        case .`subscript`:
            return "subscript"
        case .superscript:
            return "superscript"
        case .highlight:
            return "highlight"
        case .link:
            return "link"
        }
    }
}
extension AnnotationKind {
    func intoRust() throws -> RustBridge.AnnotationKind {
