/// The semantic content type of a document node.
///
/// Uses internally tagged representation (`"node_type": "heading"`) for JSON serialization.
public enum NodeContent: Codable, Sendable, Hashable {
    /// A heading element (h1-h6).
    case heading(level: UInt8, text: String)
    /// A paragraph of text.
    case paragraph(text: String)
    /// A list container (ordered or unordered). Children are `ListItem` nodes.
    case list(ordered: Bool)
    /// A single list item.
    case listItem(text: String)
    /// A table with structured cell data.
    case table(grid: TableGrid)
    /// An image element.
    case image(description: String?, src: String?, imageIndex: UInt32?)
    /// A code block or inline code.
    case code(text: String, language: String?)
    /// A block quote container.
    case quote
    /// A definition list container.
    case definitionList
    /// A definition list entry with term and description.
    case definitionItem(term: String, definition: String)
    /// A raw block preserved as-is (e.g. `<script>`, `<style>` content).
    case rawBlock(format: String, content: String)
    /// A block of key-value metadata pairs (from `<head>` meta tags).
    case metadataBlock(entries: [MetadataEntry])
    /// A section grouping container (auto-generated from heading hierarchy).
    case group(label: String?, headingLevel: UInt8?, headingText: String?)

    private enum CodingKeys: String, CodingKey {
        case nodeType = "node_type"

        case content
        case definition
        case description
        case entries
        case format
        case grid
        case headingLevel = "heading_level"
        case headingText = "heading_text"
        case imageIndex = "image_index"
        case label
        case language
        case level
        case ordered
        case src
        case term
        case text    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let type = try container.decode(String.self, forKey: .nodeType)
        switch type {
        case "heading":
            self = .heading(level: try container.decode(UInt8.self, forKey: .level), text: try container.decode(String.self, forKey: .text))
        case "paragraph":
            self = .paragraph(text: try container.decode(String.self, forKey: .text))
        case "list":
            self = .list(ordered: try container.decode(Bool.self, forKey: .ordered))
        case "list_item":
            self = .listItem(text: try container.decode(String.self, forKey: .text))
        case "table":
            self = .table(grid: try container.decode(TableGrid.self, forKey: .grid))
        case "image":
            self = .image(description: try container.decodeIfPresent(String.self, forKey: .description), src: try container.decodeIfPresent(String.self, forKey: .src), imageIndex: try container.decodeIfPresent(UInt32.self, forKey: .imageIndex))
        case "code":
            self = .code(text: try container.decode(String.self, forKey: .text), language: try container.decodeIfPresent(String.self, forKey: .language))
        case "quote":
            self = .quote
        case "definition_list":
            self = .definitionList
        case "definition_item":
            self = .definitionItem(term: try container.decode(String.self, forKey: .term), definition: try container.decode(String.self, forKey: .definition))
        case "raw_block":
            self = .rawBlock(format: try container.decode(String.self, forKey: .format), content: try container.decode(String.self, forKey: .content))
        case "metadata_block":
            self = .metadataBlock(entries: try container.decode([MetadataEntry].self, forKey: .entries))
        case "group":
            self = .group(label: try container.decodeIfPresent(String.self, forKey: .label), headingLevel: try container.decodeIfPresent(UInt8.self, forKey: .headingLevel), headingText: try container.decodeIfPresent(String.self, forKey: .headingText))
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .nodeType,
                in: container,
                debugDescription: "Unknown NodeContent type: \(type)"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .heading(let level, let text):
            try container.encode("heading", forKey: .nodeType)
            try container.encode(level, forKey: .level)
            try container.encode(text, forKey: .text)

        case .paragraph(let text):
            try container.encode("paragraph", forKey: .nodeType)
            try container.encode(text, forKey: .text)

        case .list(let ordered):
            try container.encode("list", forKey: .nodeType)
            try container.encode(ordered, forKey: .ordered)

        case .listItem(let text):
            try container.encode("list_item", forKey: .nodeType)
            try container.encode(text, forKey: .text)

        case .table(let grid):
            try container.encode("table", forKey: .nodeType)
            try container.encode(grid, forKey: .grid)

        case .image(let description, let src, let imageIndex):
            try container.encode("image", forKey: .nodeType)
            try container.encodeIfPresent(description, forKey: .description)
            try container.encodeIfPresent(src, forKey: .src)
            try container.encodeIfPresent(imageIndex, forKey: .imageIndex)

        case .code(let text, let language):
            try container.encode("code", forKey: .nodeType)
            try container.encode(text, forKey: .text)
            try container.encodeIfPresent(language, forKey: .language)

        case .quote:
            try container.encode("quote", forKey: .nodeType)
        case .definitionList:
            try container.encode("definition_list", forKey: .nodeType)
        case .definitionItem(let term, let definition):
            try container.encode("definition_item", forKey: .nodeType)
            try container.encode(term, forKey: .term)
            try container.encode(definition, forKey: .definition)

        case .rawBlock(let format, let content):
            try container.encode("raw_block", forKey: .nodeType)
            try container.encode(format, forKey: .format)
            try container.encode(content, forKey: .content)

        case .metadataBlock(let entries):
            try container.encode("metadata_block", forKey: .nodeType)
            try container.encode(entries, forKey: .entries)

        case .group(let label, let headingLevel, let headingText):
            try container.encode("group", forKey: .nodeType)
            try container.encodeIfPresent(label, forKey: .label)
            try container.encodeIfPresent(headingLevel, forKey: .headingLevel)
            try container.encodeIfPresent(headingText, forKey: .headingText)

        }
    }
}
extension NodeContent {
    /// Returns the serde wire tag identifying this variant -- the same value
    /// the pre-promotion opaque binding's `to_string()` returned -- dropping
    /// any associated payload.
    public func toString() -> String {
        switch self {
        case .heading:
            return "heading"
        case .paragraph:
            return "paragraph"
        case .list:
            return "list"
        case .listItem:
            return "list_item"
        case .table:
            return "table"
        case .image:
            return "image"
        case .code:
            return "code"
        case .quote:
            return "quote"
        case .definitionList:
            return "definition_list"
        case .definitionItem:
            return "definition_item"
        case .rawBlock:
            return "raw_block"
        case .metadataBlock:
            return "metadata_block"
        case .group:
            return "group"
        }
    }
}
extension NodeContent {
