/// URL encoding strategy for link and image destinations.
///
/// Controls how special characters in URL destinations are handled when they
/// require escaping to produce valid Markdown.
///
/// The `Angle` variant (default) wraps the destination in angle brackets:
/// `[text](<url with spaces>)`. This is the CommonMark-specified escape hatch
/// but breaks when the URL itself contains `>`.
///
/// The `Percent` variant percent-encodes every character that is not an RFC 3986
/// unreserved character or `/`, producing a destination safe for all Markdown
/// parsers: `[text](url%20with%20spaces)`.
public typealias UrlEscapeStyle = RustBridge.UrlEscapeStyle

/// Result of a visitor callback.
///
/// Allows visitors to control the conversion flow by either proceeding
/// with default behavior, providing custom output, skipping elements,
/// preserving HTML, or signaling errors.
public enum VisitResult: Codable, Sendable, Hashable {
    /// Continue with default conversion behavior
    case `continue`
    /// Replace default output with custom markdown
    ///
    /// The visitor takes full responsibility for the markdown output
    /// of this node and its children.
    case custom(field0: String)
    /// Skip this element entirely (don't output anything)
    ///
    /// The element and all its children are ignored in the output.
    case skip
    /// Preserve original HTML (don't convert to markdown)
    ///
    /// The element's raw HTML is included verbatim in the output.
    case preserveHtml
    /// Stop conversion with an error
    ///
    /// The conversion process halts and returns this error message.
    case error(field0: String)

    private enum CodingKeys: String, CodingKey {
        case type = "type"
        case output = "output"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try container.decode(String.self, forKey: .type)
        switch tag {
        case "continue":
            self = .`continue`
        case "custom":
            self = .custom(field0: try container.decode(String.self, forKey: .output))
        case "skip":
            self = .skip
        case "preserve_html":
            self = .preserveHtml
        case "error":
            self = .error(field0: try container.decode(String.self, forKey: .output))
        default:
            throw DecodingError.dataCorruptedError(
                forKey: .type,
                in: container,
                debugDescription: "Unknown VisitResult tag: \(tag)"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .`continue`:
            try container.encode("continue", forKey: .type)
        case .custom(let field0):
            try container.encode("custom", forKey: .type)
            try container.encode(field0, forKey: .output)
        case .skip:
            try container.encode("skip", forKey: .type)
        case .preserveHtml:
            try container.encode("preserve_html", forKey: .type)
        case .error(let field0):
            try container.encode("error", forKey: .type)
            try container.encode(field0, forKey: .output)
        }
    }
}

